contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testRegression_property() public {
        // Setup: owner calls approveMax, then supplies tokens to an address
        vm.prank(address(0x1));
        c.approveMax();

        // Simulate token transfer: give the contract some mAsset tokens
        // Deposit 100 mAsset tokens
        // We need a user to supply tokens - use address(0x2) as the caller
        vm.prank(address(0x2));
        // First we need to actually have the tokens - deploy a token contract or use vm.mockCall
        // Since we can't use vm.mockCall, we'll skip the token transfer and just check the balance
        // Actually, let's use a simpler approach: check that after redeem, the balanceOfToken changes

        // The key divergence: call redeemToken with an amount that would cause underflow in reference
        // In reference, imBalances[msg.sender] would underflow (since it starts at 0)
        // In buggy, it doesn't change
        vm.prank(address(0x1));
        // Try to redeem, which should revert in reference but succeed in buggy
        try c.redeemToken(100) {
            // If we get here, it's the buggy version - check that imBalances didn't change
